/**
 * Englify — English learning site.
 * Exercises are generated by an AI provider (config.aiProvider):
 *  - 'pollinations' (default) — free keyless API, no registration;
 *  - 'claude' — Claude Code CLI (`claude -p`) via the owner's subscription.
 */
const express = require('express');
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const { spawn } = require('child_process');

// ---------------------------------------------------------------------------
// Config
// ---------------------------------------------------------------------------
const CONFIG_PATH = path.join(__dirname, 'config.json');
const DEFAULT_CONFIG = {
  port: 3000,
  // Google OAuth client ID (Web application). Empty => dev login enabled.
  googleClientId: '',
  // DonationAlerts app credentials (https://www.donationalerts.com/application/clients)
  daClientId: '',
  daClientSecret: '',
  daRedirectUri: 'http://localhost:3000/api/da/callback',
  // Public donation page, e.g. https://www.donationalerts.com/r/yourname
  daDonateUrl: '',
  premiumPriceRub: 199,
  premiumDays: 30,
  freeDailyLimit: 15,
  adminEmails: [],
  // 'auto' (default) — try Ollama, then Pollinations; or force one of:
  // 'ollama' — local AI, free and unlimited; 'pollinations' — free keyless API;
  // 'claude' — Claude Code CLI via the owner's subscription
  aiProvider: 'auto',
  ollamaUrl: 'http://localhost:11434',
  ollamaModel: 'qwen2.5:3b',
  claudeModel: 'sonnet'
};
let config = { ...DEFAULT_CONFIG };
if (fs.existsSync(CONFIG_PATH)) {
  try {
    config = { ...DEFAULT_CONFIG, ...JSON.parse(fs.readFileSync(CONFIG_PATH, 'utf8')) };
  } catch (e) {
    console.error('config.json is invalid JSON, using defaults:', e.message);
  }
}

// ---------------------------------------------------------------------------
// Tiny JSON-file database
// ---------------------------------------------------------------------------
const DATA_DIR = path.join(__dirname, 'data');
const DB_PATH = path.join(DATA_DIR, 'db.json');
if (!fs.existsSync(DATA_DIR)) fs.mkdirSync(DATA_DIR, { recursive: true });

let db = {
  secret: crypto.randomBytes(32).toString('hex'),
  users: {},            // id -> user
  pool: {},             // level -> type -> [exercise]
  processedDonations: [],
  daTokens: null        // { access, refresh, expiresAt }
};
if (fs.existsSync(DB_PATH)) {
  try { db = { ...db, ...JSON.parse(fs.readFileSync(DB_PATH, 'utf8')) }; }
  catch (e) { console.error('db.json corrupted, starting fresh:', e.message); }
}
let saveTimer = null;
function saveDb() {
  clearTimeout(saveTimer);
  saveTimer = setTimeout(() => {
    fs.writeFileSync(DB_PATH, JSON.stringify(db, null, 2));
  }, 300);
}

// ---------------------------------------------------------------------------
// Sessions (signed cookie)
// ---------------------------------------------------------------------------
function sign(value) {
  return crypto.createHmac('sha256', db.secret).update(value).digest('base64url');
}
function makeSession(userId) {
  return userId + '.' + sign(userId);
}
function parseSession(cookieHeader) {
  if (!cookieHeader) return null;
  const m = /(?:^|;\s*)englify_session=([^;]+)/.exec(cookieHeader);
  if (!m) return null;
  const [userId, sig] = decodeURIComponent(m[1]).split('.');
  if (!userId || !sig) return null;
  try {
    if (!crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(sign(userId)))) return null;
  } catch { return null; }
  return db.users[userId] || null;
}

function today() {
  return new Date().toISOString().slice(0, 10);
}

function newPayCode() {
  return 'EN-' + crypto.randomBytes(3).toString('hex').toUpperCase();
}

function upsertUser({ googleSub, email, name, picture }) {
  let user = Object.values(db.users).find(u => (googleSub && u.googleSub === googleSub) || (email && u.email === email));
  if (!user) {
    user = {
      id: crypto.randomUUID(),
      googleSub: googleSub || null,
      email: email || null,
      name: name || 'Ученик',
      picture: picture || null,
      createdAt: Date.now(),
      xp: 0,
      done: 0,
      correct: 0,
      streak: 0,
      lastActiveDay: null,
      level: 'A2',
      payCode: newPayCode(),
      premiumUntil: 0,
      usage: { date: today(), count: 0 }
    };
    db.users[user.id] = user;
  } else {
    if (name) user.name = name;
    if (picture) user.picture = picture;
    if (googleSub) user.googleSub = googleSub;
  }
  saveDb();
  return user;
}

function isPremium(user) {
  return user.premiumUntil > Date.now();
}
function isAdmin(user) {
  if (user.dev) return true;
  return !!user.email && config.adminEmails.map(e => e.toLowerCase()).includes(user.email.toLowerCase());
}
function publicUser(user) {
  return {
    id: user.id, name: user.name, email: user.email, picture: user.picture,
    xp: user.xp, done: user.done, correct: user.correct, streak: user.streak,
    level: user.level, payCode: user.payCode,
    premium: isPremium(user), premiumUntil: user.premiumUntil,
    admin: isAdmin(user),
    usedToday: user.usage.date === today() ? user.usage.count : 0,
    dailyLimit: config.freeDailyLimit
  };
}

// ---------------------------------------------------------------------------
// AI providers
// ---------------------------------------------------------------------------

// Pollinations — free text generation API, no key and no registration.
async function callPollinations(prompt, timeoutMs = 120000) {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), timeoutMs);
  try {
    const res = await fetch('https://text.pollinations.ai/', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      signal: ctrl.signal,
      body: JSON.stringify({
        messages: [{ role: 'user', content: prompt }],
        model: 'openai',
        // random seed — otherwise Pollinations returns a cached identical answer
        seed: Math.floor(Math.random() * 1e9),
        private: true
      })
    });
    if (!res.ok) throw new Error('Pollinations HTTP ' + res.status + ': ' + (await res.text()).slice(0, 200));
    return (await res.text()).trim();
  } finally {
    clearTimeout(timer);
  }
}

// Claude Code CLI — uses the owner's Claude subscription, no API key.
function callClaude(prompt, timeoutMs = 180000) {
  return new Promise((resolve, reject) => {
    // `claude -p` reads the prompt from stdin; stdin avoids Windows quoting issues.
    const child = spawn('claude', ['-p', '--model', config.claudeModel], {
      shell: true,
      windowsHide: true,
      env: { ...process.env, CLAUDE_CODE_ENTRYPOINT: undefined, CLAUDECODE: undefined }
    });
    let out = '', err = '';
    const timer = setTimeout(() => { child.kill(); reject(new Error('claude CLI timeout')); }, timeoutMs);
    child.stdout.on('data', d => out += d);
    child.stderr.on('data', d => err += d);
    child.on('error', e => { clearTimeout(timer); reject(e); });
    child.on('close', code => {
      clearTimeout(timer);
      if (code === 0) resolve(out.trim());
      else reject(new Error('claude CLI exited ' + code + ': ' + err.slice(0, 500)));
    });
    child.stdin.write(prompt);
    child.stdin.end();
  });
}

// Ollama — local AI server, free and unlimited (https://ollama.com).
async function callOllama(prompt, timeoutMs = 300000) {
  const res = await fetch(config.ollamaUrl + '/api/generate', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    signal: AbortSignal.timeout(timeoutMs),
    body: JSON.stringify({
      model: config.ollamaModel,
      prompt,
      stream: false,
      options: { temperature: 0.9 }
    })
  });
  if (!res.ok) throw new Error('Ollama HTTP ' + res.status + ': ' + (await res.text()).slice(0, 200));
  const data = await res.json();
  return String(data.response || '').trim();
}

async function ollamaAvailable() {
  try {
    const res = await fetch(config.ollamaUrl + '/api/tags', { signal: AbortSignal.timeout(2000) });
    if (!res.ok) return false;
    const { models = [] } = await res.json();
    return models.some(m => m.name.startsWith(config.ollamaModel.split(':')[0]));
  } catch { return false; }
}

async function callAI(prompt, timeoutMs) {
  switch (config.aiProvider) {
    case 'claude': return callClaude(prompt, timeoutMs);
    case 'ollama': return callOllama(prompt, timeoutMs);
    case 'pollinations': return callPollinations(prompt, timeoutMs);
    default: { // 'auto': local Ollama first, then the free web API
      if (await ollamaAvailable()) return callOllama(prompt, timeoutMs);
      return callPollinations(prompt, timeoutMs);
    }
  }
}

function extractJson(text) {
  const start = text.indexOf('[');
  const end = text.lastIndexOf(']');
  if (start !== -1 && end > start) {
    try { return JSON.parse(text.slice(start, end + 1)); } catch { /* try object form below */ }
  }
  // Some models wrap the array in an object: {"exercises":[...]}
  const oStart = text.indexOf('{');
  const oEnd = text.lastIndexOf('}');
  if (oStart !== -1 && oEnd > oStart) {
    const obj = JSON.parse(text.slice(oStart, oEnd + 1));
    const arr = Object.values(obj).find(Array.isArray);
    if (arr) return arr;
    return [obj]; // single exercise / verdict object
  }
  throw new Error('no JSON in response');
}

const TYPES = ['mchoice', 'gap', 'translate', 'order', 'listen'];
const LEVELS = ['A1', 'A2', 'B1', 'B2', 'C1'];

const TYPE_SPECS = {
  mchoice: `{"type":"mchoice","question":"<grammar or vocabulary question in Russian or an English sentence with a choice>","options":["...","...","...","..."],"correct":<index 0-3>,"explanation":"<short explanation in Russian>"}`,
  gap: `{"type":"gap","sentence":"<English sentence with ___ for the missing word>","answer":"<the missing word>","translation":"<Russian translation of the full sentence>","explanation":"<short explanation in Russian>"}`,
  translate: `{"type":"translate","ru":"<sentence in Russian>","answers":["<best English translation>","<acceptable variant>","<acceptable variant>"],"hint":"<one key word or grammar hint in Russian>"}`,
  order: `{"type":"order","words":["<shuffled","words","of","sentence>"],"answer":"<the correct English sentence>","ru":"<Russian translation>"}`,
  listen: `{"type":"listen","text":"<English sentence to be read aloud, 5-12 words>","ru":"<Russian translation>"}`
};

const TOPICS = [
  'daily life', 'travel', 'work and office', 'food and cooking', 'technology', 'nature and weather',
  'sports', 'music and movies', 'shopping', 'health', 'family and friends', 'school and studying',
  'hobbies', 'transport', 'animals', 'holidays', 'money', 'clothes and fashion', 'city life', 'emotions'
];
function pickTopics(n) {
  const shuffled = [...TOPICS].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, n);
}

function buildPrompt(level, type, n) {
  return `You are an English exercise generator for Russian-speaking students.
Generate exactly ${n} exercises of type "${type}" for CEFR level ${level}.
Use these topics: ${pickTopics(3).join(', ')} (variation seed: ${crypto.randomBytes(4).toString('hex')}).
Every exercise must be about a different sentence — no two exercises may share the same sentence or answer.
Vary grammar points appropriate for ${level}.
Return ONLY a JSON array, no markdown, no commentary. Each element must match this schema exactly:
${TYPE_SPECS[type]}
Rules:
- All explanations, hints and translations must be in Russian.
- English content difficulty must match CEFR ${level}.
- For "order": 5-9 words, shuffled, no duplicates of the correct order.
- For "gap": exactly one blank written as ___.
- For "translate": 2-4 accepted answer variants, first is the most natural.
- Output must be valid JSON.`;
}

// Content fingerprint used to keep already-seen exercises out of rotation.
function exHash(ex) {
  const key = [ex.type, ex.question, ex.sentence, ex.ru, ex.text, ex.answer, (ex.answers || [])[0]]
    .filter(Boolean).join('|').toLowerCase().replace(/\s+/g, ' ');
  return crypto.createHash('sha1').update(key).digest('hex').slice(0, 12);
}
function rememberServed(user, hash) {
  user.recent = user.recent || [];
  user.recent.push(hash);
  if (user.recent.length > 50) user.recent.splice(0, user.recent.length - 50);
  db.servedHashes = db.servedHashes || [];
  if (!db.servedHashes.includes(hash)) {
    db.servedHashes.push(hash);
    if (db.servedHashes.length > 500) db.servedHashes.splice(0, db.servedHashes.length - 500);
  }
}

const inFlight = new Set();
async function refillPool(level, type) {
  const key = level + ':' + type;
  if (inFlight.has(key)) return;
  inFlight.add(key);
  try {
    const raw = await callAI(buildPrompt(level, type, 6));
    db.pool[level] = db.pool[level] || {};
    const pool = db.pool[level][type] = db.pool[level][type] || [];
    const known = new Set(pool.map(exHash).concat(db.servedHashes || []));
    const items = extractJson(raw).filter(it => it && it.type === type && !known.has(exHash(it)));
    if (!items.length) throw new Error('empty batch (all duplicates?)');
    pool.push(...items);
    saveDb();
    console.log(`[pool] +${items.length} ${type}/${level} (now ${pool.length})`);
  } catch (e) {
    console.error(`[pool] refill ${key} failed:`, e.message);
  } finally {
    inFlight.delete(key);
  }
}

