// ---------------------------------------------------------------------------
// DonationAlerts
// ---------------------------------------------------------------------------
const DA_BASE = 'https://www.donationalerts.com';

async function daRefreshIfNeeded() {
  const t = db.daTokens;
  if (!t) return null;
  if (t.expiresAt && t.expiresAt - Date.now() < 60000 && t.refresh) {
    try {
      const res = await fetch(DA_BASE + '/oauth/token', {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: new URLSearchParams({
          grant_type: 'refresh_token',
          refresh_token: t.refresh,
          client_id: config.daClientId,
          client_secret: config.daClientSecret,
          scope: 'oauth-user-show oauth-donation-index'
        })
      });
      const data = await res.json();
      if (data.access_token) {
        db.daTokens = {
          access: data.access_token,
          refresh: data.refresh_token || t.refresh,
          expiresAt: Date.now() + (data.expires_in || 3600) * 1000
        };
        saveDb();
      }
    } catch (e) { console.error('[DA] token refresh failed:', e.message); }
  }
  return db.daTokens && db.daTokens.access;
}

async function daPollDonations() {
  const access = await daRefreshIfNeeded();
  if (!access) return { checked: false, reason: 'DonationAlerts не подключен' };
  try {
    const res = await fetch(DA_BASE + '/api/v1/alerts/donations?page=1', {
      headers: { Authorization: 'Bearer ' + access }
    });
    if (!res.ok) return { checked: false, reason: 'DA API: HTTP ' + res.status };
    const { data = [] } = await res.json();
    let activated = 0;
    for (const d of data) {
      if (db.processedDonations.includes(d.id)) continue;
      const msg = String(d.message || '').toUpperCase();
      const user = Object.values(db.users).find(u => u.payCode && msg.includes(u.payCode.toUpperCase()));
      if (!user) continue;
      const amountOk = d.currency !== 'RUB' || Number(d.amount) >= config.premiumPriceRub;
      if (!amountOk) continue;
      db.processedDonations.push(d.id);
      const base = Math.max(user.premiumUntil, Date.now());
      user.premiumUntil = base + config.premiumDays * 24 * 3600 * 1000;
      activated++;
      console.log(`[DA] premium activated for ${user.email || user.name} until ${new Date(user.premiumUntil).toISOString()}`);
    }
    if (activated) saveDb();
    return { checked: true, activated };
  } catch (e) {
    return { checked: false, reason: e.message };
  }
}
setInterval(() => { if (db.daTokens) daPollDonations(); }, 90000);

// ---------------------------------------------------------------------------
// HTTP API
// ---------------------------------------------------------------------------
const app = express();
app.use(express.json({ limit: '100kb' }));
app.use(express.static(path.join(__dirname, 'public')));

function auth(req, res, next) {
  const user = parseSession(req.headers.cookie);
  if (!user) return res.status(401).json({ error: 'Не авторизован' });
  req.user = user;
  next();
}
function setSessionCookie(res, userId) {
  res.setHeader('Set-Cookie',
    `englify_session=${encodeURIComponent(makeSession(userId))}; HttpOnly; Path=/; Max-Age=${180 * 24 * 3600}; SameSite=Lax`);
}

app.get('/api/config', (req, res) => {
  res.json({
    googleClientId: config.googleClientId,
    devLogin: !config.googleClientId,
    premiumPriceRub: config.premiumPriceRub,
    premiumDays: config.premiumDays,
    donateUrl: config.daDonateUrl,
    daConnected: !!db.daTokens,
    levels: LEVELS,
    types: TYPES
  });
});

// --- Auth ---
app.post('/api/auth/google', async (req, res) => {
  const { credential } = req.body || {};
  if (!credential) return res.status(400).json({ error: 'Нет токена' });
  if (!config.googleClientId) return res.status(400).json({ error: 'Google Client ID не настроен' });
  try {
    const r = await fetch('https://oauth2.googleapis.com/tokeninfo?id_token=' + encodeURIComponent(credential));
    const info = await r.json();
    if (!r.ok || info.aud !== config.googleClientId) {
      return res.status(401).json({ error: 'Токен Google не прошёл проверку' });
    }
    const user = upsertUser({ googleSub: info.sub, email: info.email, name: info.name, picture: info.picture });
    setSessionCookie(res, user.id);
    res.json({ user: publicUser(user) });
  } catch (e) {
    res.status(500).json({ error: 'Ошибка проверки токена: ' + e.message });
  }
});

// Dev login — only available while Google client ID is not configured.
app.post('/api/auth/dev', (req, res) => {
  if (config.googleClientId) return res.status(403).json({ error: 'Отключено: настроен вход через Google' });
  const name = (req.body && String(req.body.name || '').trim()) || 'Тестовый ученик';
  const user = upsertUser({ email: 'dev@localhost', name });
  user.dev = true;
  saveDb();
  setSessionCookie(res, user.id);
  res.json({ user: publicUser(user) });
});

app.post('/api/logout', (req, res) => {
  res.setHeader('Set-Cookie', 'englify_session=; HttpOnly; Path=/; Max-Age=0');
  res.json({ ok: true });
});

app.get('/api/me', auth, (req, res) => res.json({ user: publicUser(req.user) }));

app.post('/api/level', auth, (req, res) => {
  const level = String((req.body || {}).level || '');
  if (!LEVELS.includes(level)) return res.status(400).json({ error: 'Неверный уровень' });
  req.user.level = level;
  saveDb();
  res.json({ user: publicUser(req.user) });
});

// --- Exercises ---
app.get('/api/exercise', auth, (req, res) => {
  const user = req.user;
  const level = LEVELS.includes(req.query.level) ? req.query.level : user.level;
  let type = TYPES.includes(req.query.type) ? req.query.type : TYPES[Math.floor(Math.random() * TYPES.length)];

  if (user.usage.date !== today()) user.usage = { date: today(), count: 0 };
  if (!isPremium(user) && user.usage.count >= config.freeDailyLimit) {
    return res.status(402).json({ error: 'limit', message: 'Дневной лимит бесплатных упражнений исчерпан. Оформите Premium!' });
  }

  const pool = (db.pool[level] && db.pool[level][type]) || [];
  const recent = new Set(user.recent || []);
  let exercise, source;
  // Prefer a pool exercise the user hasn't seen yet.
  let idx = pool.findIndex(ex => !recent.has(exHash(ex)));
  if (idx === -1 && pool.length > 0) idx = 0;
  if (idx !== -1) {
    exercise = pool.splice(idx, 1)[0];
    source = 'ai';
  } else {
    const fb = FALLBACK[type];
    const fresh = fb.filter(ex => !recent.has(exHash(ex)));
    exercise = (fresh.length ? fresh : fb)[Math.floor(Math.random() * (fresh.length ? fresh.length : fb.length))];
    source = 'builtin';
  }
  // Refill in the background when the pool runs low.
  if (pool.length < 4) refillPool(level, type);

  rememberServed(user, exHash(exercise));
  user.usage.count++;
  saveDb();
  res.json({ exercise, source, level, usedToday: user.usage.count, dailyLimit: config.freeDailyLimit, premium: isPremium(user) });
});

app.post('/api/result', auth, (req, res) => {
  const { correct } = req.body || {};
  const user = req.user;
  user.done++;
  if (correct) { user.correct++; user.xp += 10; } else { user.xp += 2; }
  const t = today();
  if (user.lastActiveDay !== t) {
    const yesterday = new Date(Date.now() - 24 * 3600 * 1000).toISOString().slice(0, 10);
    user.streak = user.lastActiveDay === yesterday ? user.streak + 1 : 1;
    user.lastActiveDay = t;
  }
  saveDb();
  res.json({ user: publicUser(user) });
});

// AI free-form answer check (e.g. translations) — uses Claude via subscription.
app.post('/api/ai/check', auth, async (req, res) => {
  const { ru, expected, answer } = req.body || {};
  if (!ru || !answer) return res.status(400).json({ error: 'Нет данных' });
  const user = req.user;
  if (user.usage.date !== today()) user.usage = { date: today(), count: 0 };
  if (!isPremium(user) && user.usage.count >= config.freeDailyLimit) {
    return res.status(402).json({ error: 'limit', message: 'Дневной лимит исчерпан. Оформите Premium!' });
  }
  try {
    const raw = await callAI(
      `A Russian-speaking student translated the sentence "${String(ru).slice(0, 300)}" into English as: "${String(answer).slice(0, 300)}".
Reference translation: "${String(expected || '').slice(0, 300)}".
Judge if the student's translation is acceptable (correct grammar and meaning; minor stylistic differences are OK).
Return ONLY a JSON array with one object: [{"ok":true|false,"comment":"<1-2 sentence feedback in Russian, mention the mistake if any>"}]`,
      90000
    );
    const [verdict] = extractJson(raw);
    res.json({ ok: !!verdict.ok, comment: String(verdict.comment || '') });
  } catch (e) {
    res.status(500).json({ error: 'ИИ-проверка недоступна: ' + e.message });
  }
});

// --- Subscription ---
app.post('/api/subscription/check', auth, async (req, res) => {
  const result = await daPollDonations();
  res.json({ ...result, user: publicUser(req.user) });
});

// One-time DonationAlerts OAuth connection (admin only).
app.get('/api/da/connect', (req, res) => {
  const user = parseSession(req.headers.cookie);
  if (!user || !isAdmin(user)) return res.status(403).send('Только для администратора');
  if (!config.daClientId) return res.status(400).send('daClientId не указан в config.json');
  const url = DA_BASE + '/oauth/authorize?' + new URLSearchParams({
    client_id: config.daClientId,
    redirect_uri: config.daRedirectUri,
    response_type: 'code',
    scope: 'oauth-user-show oauth-donation-index'
  });
  res.redirect(url);
});

app.get('/api/da/callback', async (req, res) => {
  const code = req.query.code;
  if (!code) return res.status(400).send('Нет кода авторизации');
  try {
    const r = await fetch(DA_BASE + '/oauth/token', {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({
        grant_type: 'authorization_code',
        client_id: config.daClientId,
        client_secret: config.daClientSecret,
        redirect_uri: config.daRedirectUri,
        code
      })
    });
    const data = await r.json();
    if (!data.access_token) return res.status(500).send('DA не вернул токен: ' + JSON.stringify(data));
    db.daTokens = {
      access: data.access_token,
      refresh: data.refresh_token || null,
      expiresAt: Date.now() + (data.expires_in || 3600) * 1000
    };
    saveDb();
    res.send('DonationAlerts подключен! Можно закрыть вкладку.');
  } catch (e) {
    res.status(500).send('Ошибка: ' + e.message);
  }
});

// Manual premium grant (admin).
app.post('/api/admin/grant', auth, (req, res) => {
  if (!isAdmin(req.user)) return res.status(403).json({ error: 'Только для администратора' });
  const { email, days } = req.body || {};
  const target = Object.values(db.users).find(u => u.email === email);
  if (!target) return res.status(404).json({ error: 'Пользователь не найден' });
  const base = Math.max(target.premiumUntil, Date.now());
  target.premiumUntil = base + (Number(days) || config.premiumDays) * 24 * 3600 * 1000;
  saveDb();
  res.json({ ok: true, premiumUntil: target.premiumUntil });
});

